targets.query:
import "internal/debug"

from(bucket: v.defaultBucket)
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "defenestrator_usage" and r.provider == "${provider}" and (r._field == "u5" or r._field == "reset5"))
  |> pivot(rowKey: ["_time"], columnKey: ["_field"], valueColumn: "_value")
  |> filter(fn: (r) => exists r.u5)
  |> map(fn: (r) => {
      left = if exists r.reset5 then (r.reset5 - float(v: int(v: r._time)) / 1000000000.0) / 18000.0 else -1.0
      pace = if left < 0.0 then debug.null(type: "float") else if left > 1.0 then 0.0 else 100.0 * (1.0 - left)
      return {_time: r._time, "5-hour used": r.u5, "even pace": pace, "over pace": if exists pace then (if r.u5 > pace then r.u5 else pace) else debug.null(type: "float")}
    })

from(bucket: v.defaultBucket)
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "defenestrator_usage" and r.provider == "${provider}" and (r._field == "u7" or r._field == "reset7"))
  |> pivot(rowKey: ["_time"], columnKey: ["_field"], valueColumn: "_value")
  |> filter(fn: (r) => exists r.u7 and exists r.reset7)
  |> map(fn: (r) => {
      left = (r.reset7 - float(v: int(v: r._time)) / 1000000000.0) / 604800.0
      pace = if left > 1.0 then 0.0 else if left < 0.0 then 100.0 else 100.0 * (1.0 - left)
      return {_time: r._time, "7-day used": r.u7, "even pace": pace, "over pace": if r.u7 > pace then r.u7 else pace}
    })
